class Solution { private fun day(date:String):Int{val days=intArrayOf(31,28,31,30,31,30,31,31,30,31,30,31);val month=date.substring(0,2).toInt();var value=date.substring(3).toInt();for(i in 0 until month-1)value+=days[i];return value};fun countDaysTogether(arriveAlice:String,leaveAlice:String,arriveBob:String,leaveBob:String):Int{return maxOf(0,minOf(day(leaveAlice),day(leaveBob))-maxOf(day(arriveAlice),day(arriveBob))+1)} }
